#!/usr/bin/env python3
"""Generate the interface code from interfaces/schema (single source, after the ICD).

Outputs:
- interfaces/c/pp_types.h                 C structs for the planner
- interfaces/<module>.py, __init__.py     Python dataclasses for sim, eval, tests
- adapters/sil/pp_ctypes.py               ctypes mirror for the SIL adapter
- tests/interfaces/pp_layout_probe.c      sizeof/offsetof probe for the layout test

Usage: python3 interfaces/gen.py [--check]
--check writes nothing and exits 1 when a generated file is out of date.
"""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
SCHEMA = ROOT / "interfaces" / "schema"
BANNER = "Generated by interfaces/gen.py from interfaces/schema. Do not edit."

SCALARS = {
    # name: (C type, ctypes type, Python annotation, unsigned bits or None)
    "bool": ("bool", "ctypes.c_bool", "bool", None),
    "uint8": ("uint8_t", "ctypes.c_uint8", "int", 8),
    "uint32": ("uint32_t", "ctypes.c_uint32", "int", 32),
    "uint64": ("uint64_t", "ctypes.c_uint64", "int", 64),
    "float32": ("float", "ctypes.c_float", "float", None),
}


class _Loader(yaml.SafeLoader):
    """YAML 1.1 reads OFF, ON, YES, NO as booleans. Only true/false are booleans here."""


_Loader.yaml_implicit_resolvers = {
    key: [(tag, regexp) for tag, regexp in resolvers if tag != "tag:yaml.org,2002:bool"]
    for key, resolvers in yaml.SafeLoader.yaml_implicit_resolvers.items()
}
_Loader.add_implicit_resolver(
    "tag:yaml.org,2002:bool", re.compile(r"^(?:true|false)$"), list("tf"))


def snake(name: str) -> str:
    return re.sub(r"(?<=[a-z0-9])([A-Z])", r"_\1", name.replace("2D", "2d")).lower()


def c_type_name(name: str) -> str:
    return f"pp_{snake(name)}_t"


@dataclass
class Field:
    name: str
    type: str
    count: str | int | None = None
    unit: str | None = None
    doc: str | None = None
    received: bool = False
    sent: bool = False


@dataclass
class Struct:
    name: str
    module: str
    doc: str | None
    fields: list[Field]


@dataclass
class Enum:
    name: str
    module: str
    doc: str | None
    values: dict[str, int]


@dataclass
class Constant:
    name: str
    module: str
    type: str
    value: int | float
    doc: str | None


@dataclass
class Schema:
    modules: list[str] = field(default_factory=list)
    icd: dict[str, str] = field(default_factory=dict)
    constants: dict[str, Constant] = field(default_factory=dict)
    enums: dict[str, Enum] = field(default_factory=dict)
    structs: dict[str, Struct] = field(default_factory=dict)

    def owner(self, name: str) -> str:
        for table in (self.constants, self.enums, self.structs):
            if name in table:
                return table[name].module
        raise KeyError(name)


def load() -> Schema:
    schema = Schema()
    for path in sorted(SCHEMA.rglob("*.yaml")):
        module = path.relative_to(SCHEMA).with_suffix("").as_posix().replace("/", ".")
        data = yaml.load(path.read_text(encoding="utf-8"), Loader=_Loader) or {}
        schema.modules.append(module)
        schema.icd[module] = str(data.get("icd", ""))
        for name, spec in (data.get("constants") or {}).items():
            schema.constants[name] = Constant(name, module, spec["type"], spec["value"], spec.get("doc"))
        for name, spec in (data.get("enums") or {}).items():
            values = {str(k): int(v) for k, v in spec["values"].items()}
            schema.enums[name] = Enum(name, module, spec.get("doc"), values)
        for name, spec in (data.get("structs") or {}).items():
            fields = [Field(**f) for f in spec["fields"]]
            schema.structs[name] = Struct(name, module, spec.get("doc"), fields)
    _validate(schema)
    return schema


def _validate(schema: Schema) -> None:
    names = list(schema.constants) + list(schema.enums) + list(schema.structs)
    duplicates = {n for n in names if names.count(n) > 1}
    if duplicates:
        raise SystemExit(f"Duplicate names in schema: {sorted(duplicates)}")
    for struct in schema.structs.values():
        for f in struct.fields:
            if f.type not in SCALARS and f.type not in schema.enums and f.type not in schema.structs:
                raise SystemExit(f"{struct.name}.{f.name}: unknown type {f.type}")
            if isinstance(f.count, str) and f.count not in schema.constants:
                raise SystemExit(f"{struct.name}.{f.name}: unknown count {f.count}")
            if (f.received or f.sent) and f.type not in schema.structs:
                raise SystemExit(f"{struct.name}.{f.name}: received/sent needs a struct type")


def struct_order(schema: Schema) -> list[Struct]:
    """Structs in dependency order."""
    done: list[str] = []

    def visit(name: str, stack: tuple[str, ...]) -> None:
        if name in done:
            return
        if name in stack:
            raise SystemExit(f"Cycle in schema: {' -> '.join(stack + (name,))}")
        for f in schema.structs[name].fields:
            if f.type in schema.structs:
                visit(f.type, stack + (name,))
        done.append(name)

    for name in schema.structs:
        visit(name, ())
    return [schema.structs[n] for n in done]


def received_types(schema: Schema) -> list[str]:
    seen: list[str] = []
    for s in schema.structs.values():
        for f in s.fields:
            if f.received and f.type not in seen:
                seen.append(f.type)
    return seen


def count_value(schema: Schema, count: str | int) -> int:
    return int(schema.constants[count].value) if isinstance(count, str) else int(count)


# ---------------------------------------------------------------- C header

def _c_literal(c: Constant) -> str:
    if c.type == "float":
        return f"({float(c.value)!r}F)"
    if c.type == "uint64":
        return f"({int(c.value)}ULL)"
    return f"({int(c.value)}U)"


def _comment(*parts: str | None) -> str:
    text = "; ".join(p for p in parts if p)
    return f" /* {text} */" if text else ""


def gen_c(schema: Schema) -> str:
    out = [f"/* {BANNER} */", "/* Interface Control Document types of the path planner. C11. */", "",
           "#ifndef PP_TYPES_H", "#define PP_TYPES_H", "",
           "#include <stdbool.h>", "#include <stdint.h>", "",
           "#ifdef __cplusplus", 'extern "C" {', "#endif", ""]
    for module in schema.modules:
        consts = [c for c in schema.constants.values() if c.module == module]
        enums = [e for e in schema.enums.values() if e.module == module]
        if not consts and not enums:
            continue
        out.append(f"/* ---- {module} (Interface Control Document {schema.icd[module]}) ---- */")
        for c in consts:
            out.append(f"#define PP_{c.name} {_c_literal(c)}{_comment(c.doc)}")
        for e in enums:
            out.append(f"typedef uint8_t {c_type_name(e.name)};{_comment(e.doc)}")
            prefix = f"PP_{snake(e.name).upper()}_"
            for value_name, value in e.values.items():
                out.append(f"#define {prefix}{value_name} (({c_type_name(e.name)}){value}U)")
        out.append("")
    received = received_types(schema)
    for s in struct_order(schema):
        out.append(f"/* {s.module} (Interface Control Document {schema.icd[s.module]}){': ' + s.doc if s.doc else ''} */")
        out.append("typedef struct {")
        for f in s.fields:
            note = _comment(f"[{f.unit}]" if f.unit else None, f.doc)
            if f.received:
                out.append(f"    {c_type_name('Received' + f.type)} {f.name};{note}")
                continue
            if f.sent:
                out.append(f"    bool {f.name}_sent;")
            ctype = SCALARS[f.type][0] if f.type in SCALARS else c_type_name(f.type)
            dim = ""
            if f.count is not None:
                dim = f"[PP_{f.count}]" if isinstance(f.count, str) else f"[{f.count}]"
            out.append(f"    {ctype} {f.name}{dim};{note}")
        out.append(f"}} {c_type_name(s.name)};")
        out.append("")
        if s.name in received:
            out.append(f"/* {s.name} as received: present = false until the first message arrives */")
            out.append("typedef struct {")
            out.append("    bool present;")
            out.append("    uint64_t rx_us; /* [us] delivery time, receiver clock */")
            out.append(f"    {c_type_name(s.name)} message;")
            out.append(f"}} {c_type_name('Received' + s.name)};")
            out.append("")
    out += ["#ifdef __cplusplus", "}", "#endif", "", "#endif /* PP_TYPES_H */", ""]
    return "\n".join(out)


# ---------------------------------------------------------------- Python

def _py_path(module: str) -> Path:
    return ROOT / "interfaces" / Path(*module.split(".")).with_suffix(".py")


def _py_annotation(schema: Schema, f: Field) -> str:
    base = SCALARS[f.type][2] if f.type in SCALARS else f.type
    if f.received:
        return f"Received[{base}] | None"
    if f.sent:
        return f"{base} | None"
    if f.count is not None:
        return f"tuple[{base}, ...]"
    return base


def gen_python_module(schema: Schema, module: str) -> str:
    consts = [c for c in schema.constants.values() if c.module == module]
    enums = [e for e in schema.enums.values() if e.module == module]
    structs = [s for s in struct_order(schema) if s.module == module]
    used = {f.type for s in structs for f in s.fields} | {f.count for s in structs for f in s.fields if isinstance(f.count, str)}
    imports: dict[str, set[str]] = {}
    for name in sorted(n for n in used if n and n not in SCALARS):
        owner = schema.owner(name)
        if owner != module:
            imports.setdefault(owner, set()).add(name)
    has_received = any(f.received for s in structs for f in s.fields)

    out = [f'"""{module}: Interface Control Document {schema.icd[module]}.', "", f"{BANNER}", '"""', "",
           "from __future__ import annotations", "", "from dataclasses import dataclass"]
    if enums:
        out.append("from enum import IntEnum")
    if has_received:
        out.append("from typing import Generic, TypeVar")
    out.append("")
    helpers = set()
    for s in structs:
        for f in s.fields:
            if f.received:
                helpers.add("check_uint")
            elif f.sent:
                continue
            elif f.count is not None:
                helpers.add("check_array")
            elif f.type in schema.enums:
                helpers.add("check_enum")
            elif f.type in SCALARS and SCALARS[f.type][3]:
                helpers.add("check_uint")
    if helpers:
        out.append(f"from interfaces._validate import {', '.join(sorted(helpers))}")
    for owner in sorted(imports):
        out.append(f"from interfaces.{owner} import {', '.join(sorted(imports[owner]))}")
    out += ["", ""]
    for c in consts:
        value = float(c.value) if c.type == "float" else int(c.value)
        out.append(f"{c.name} = {value!r}{'  # ' + c.doc if c.doc else ''}")
    if consts:
        out += ["", ""]
    for e in enums:
        out.append(f"class {e.name}(IntEnum):")
        if e.doc:
            out.append(f'    """{e.doc}"""')
            out.append("")
        for value_name, value in e.values.items():
            out.append(f"    {value_name} = {value}")
        out += ["", ""]
    if has_received:
        out += ['T = TypeVar("T")', "", "",
                "@dataclass(frozen=True, slots=True)",
                "class Received(Generic[T]):",
                '    """Newest message of an input and its delivery time (receiver clock)."""', "",
                "    message: T",
                "    rx_us: int", "",
                "    def __post_init__(self) -> None:",
                '        check_uint(self.rx_us, 64, "rx_us")', "", ""]
    for s in structs:
        out.append("@dataclass(frozen=True, slots=True)")
        out.append(f"class {s.name}:")
        if s.doc:
            out.append(f'    """{s.doc}"""')
            out.append("")
        optional = False
        for f in s.fields:
            note = "  # " + "; ".join(p for p in (f"[{f.unit}]" if f.unit else None, f.doc) if p) if (f.unit or f.doc) else ""
            default = ""
            if f.received or f.sent:
                default = " = None"
                optional = True
            elif optional:
                raise SystemExit(f"{s.name}.{f.name}: required field after an optional one")
            out.append(f"    {f.name}: {_py_annotation(schema, f)}{default}{note}")
        checks = []
        for f in s.fields:
            if f.received or f.sent:
                continue
            if f.count is not None:
                n = f.count if isinstance(f.count, str) else str(f.count)
                checks.append(f'        check_array(self, "{f.name}", {n})')
            elif f.type in schema.enums:
                checks.append(f'        check_enum(self, "{f.name}", {f.type})')
            elif f.type in SCALARS and SCALARS[f.type][3]:
                checks.append(f'        check_uint(self.{f.name}, {SCALARS[f.type][3]}, "{f.name}")')
        if checks:
            out += ["", "    def __post_init__(self) -> None:"] + checks
        out += ["", ""]
    return "\n".join(out).rstrip() + "\n"


VALIDATE = f'''"""Structural checks of the generated interface dataclasses.

{BANNER}

Only what the C struct cannot represent is checked here: array length, unsigned
integer width, enum value. Value ranges (width <= 2.5 m, confidence 0..1, ...) are
behaviour of the receiver, so the planner checks them and tests can send bad values.
"""

from enum import IntEnum


def check_uint(value: int, bits: int, name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value < 2**bits:
        raise ValueError(f"{{name}} must be an unsigned {{bits}}-bit integer, got {{value!r}}")


def check_array(obj: object, name: str, count: int) -> None:
    value = tuple(getattr(obj, name))
    if len(value) != count:
        raise ValueError(f"{{name}} needs exactly {{count}} elements, got {{len(value)}}")
    object.__setattr__(obj, name, value)


def check_enum(obj: object, name: str, enum: type[IntEnum]) -> None:
    object.__setattr__(obj, name, enum(getattr(obj, name)))
'''


def gen_python_init(schema: Schema) -> str:
    out = [f'"""Interface types of the path planner (Interface Control Document).', "",
           f"{BANNER}", "Change the ICD first, then interfaces/schema, then run interfaces/gen.py.", '"""', ""]
    names: list[str] = []
    for module in schema.modules:
        public = [c for c in schema.constants if schema.constants[c].module == module]
        public += [e for e in schema.enums if schema.enums[e].module == module]
        public += [s for s in schema.structs if schema.structs[s].module == module]
        if any(f.received for s in schema.structs.values() if s.module == module for f in s.fields):
            public.append("Received")
        if public:
            out.append(f"from interfaces.{module} import {', '.join(public)}")
            names += public
    out.append("from interfaces.planner import EgoMotionQuery, Planner, PlannerFactory")
    names += ["EgoMotionQuery", "Planner", "PlannerFactory"]
    out += ["", "__all__ = ["] + [f'    "{n}",' for n in sorted(names)] + ["]", ""]
    return "\n".join(out)


# ---------------------------------------------------------------- ctypes

def gen_ctypes(schema: Schema) -> str:
    out = [f'"""ctypes mirror of interfaces/c/pp_types.h for the SIL adapter.', "", BANNER, '"""', "",
           "import ctypes", "", ""]
    for c in schema.constants.values():
        if c.type != "float":
            out.append(f"{c.name} = {int(c.value)}")
    out += ["", ""]
    received = received_types(schema)
    specs: list[str] = []
    for s in struct_order(schema):
        fields, spec = [], []
        for f in s.fields:
            if f.received:
                fields.append(f'("{f.name}", Received{f.type}C)')
                spec.append(f'("{f.name}", "received", "{f.type}")')
                continue
            if f.sent:
                fields.append(f'("{f.name}_sent", ctypes.c_bool)')
            if f.type in SCALARS:
                ctype, kind, ref = SCALARS[f.type][1], "scalar", None
            elif f.type in schema.enums:
                ctype, kind, ref = "ctypes.c_uint8", "enum", f.type
            else:
                ctype, kind, ref = f"{f.type}C", "struct", f.type
            if f.count is not None:
                ctype = f"{ctype} * {count_value(schema, f.count)}"
                kind = "array_" + kind
            if f.sent:
                kind = "sent"
            fields.append(f'("{f.name}", {ctype})')
            spec.append(f'("{f.name}", "{kind}", {ref!r})')
        out.append(f"class {s.name}C(ctypes.Structure):")
        out.append("    _fields_ = [")
        out += [f"        {x}," for x in fields]
        out += ["    ]", "", ""]
        specs.append(f'    "{s.name}": [{", ".join(spec)}],')
        if s.name in received:
            out += [f"class Received{s.name}C(ctypes.Structure):",
                    "    _fields_ = [",
                    '        ("present", ctypes.c_bool),',
                    '        ("rx_us", ctypes.c_uint64),',
                    f'        ("message", {s.name}C),',
                    "    ]", "", ""]
    out.append("# Field kinds that drive the Python <-> C conversion: (name, kind, referenced type)")
    out.append("FIELD_SPECS = {")
    out += specs
    out += ["}", ""]
    return "\n".join(out)


# ---------------------------------------------------------------- layout probe

def gen_probe(schema: Schema) -> str:
    out = [f"/* {BANNER} */",
           "/* Exports sizeof and offsetof of every interface struct for tests/interfaces/test_layout.py. */",
           "", "#include <stddef.h>", "#include <string.h>", "", '#include "pp_types.h"', "",
           "size_t pp_probe_sizeof(const char *type_name);",
           "size_t pp_probe_offsetof(const char *type_name, const char *field_name);", "",
           "size_t pp_probe_sizeof(const char *type_name)", "{", "    size_t result = 0U;"]
    entries = [(s.name, c_type_name(s.name)) for s in struct_order(schema)]
    entries += [(f"Received{t}", c_type_name("Received" + t)) for t in received_types(schema)]
    for i, (name, ctype) in enumerate(entries):
        kw = "if" if i == 0 else "} else if"
        out.append(f'    {kw} (strcmp(type_name, "{name}") == 0) {{')
        out.append(f"        result = sizeof({ctype});")
    out += ["    } else {", "        result = 0U;", "    }", "    return result;", "}", "",
            "size_t pp_probe_offsetof(const char *type_name, const char *field_name)", "{",
            "    size_t result = (size_t)-1;"]
    rows = []
    for s in struct_order(schema):
        for f in s.fields:
            if f.sent:
                rows.append((s.name, c_type_name(s.name), f"{f.name}_sent"))
            rows.append((s.name, c_type_name(s.name), f.name))
    for t in received_types(schema):
        for fname in ("present", "rx_us", "message"):
            rows.append((f"Received{t}", c_type_name("Received" + t), fname))
    for i, (name, ctype, fname) in enumerate(rows):
        kw = "if" if i == 0 else "} else if"
        out.append(f'    {kw} ((strcmp(type_name, "{name}") == 0) && (strcmp(field_name, "{fname}") == 0)) {{')
        out.append(f"        result = offsetof({ctype}, {fname});")
    out += ["    } else {", "        result = (size_t)-1;", "    }", "    return result;", "}", ""]
    return "\n".join(out)


# ---------------------------------------------------------------- main

def outputs(schema: Schema) -> dict[Path, str]:
    files = {
        ROOT / "interfaces" / "c" / "pp_types.h": gen_c(schema),
        ROOT / "interfaces" / "_validate.py": VALIDATE,
        ROOT / "interfaces" / "__init__.py": gen_python_init(schema),
        ROOT / "adapters" / "sil" / "pp_ctypes.py": gen_ctypes(schema),
        ROOT / "tests" / "interfaces" / "pp_layout_probe.c": gen_probe(schema),
    }
    for module in schema.modules:
        files[_py_path(module)] = gen_python_module(schema, module)
        package = _py_path(module).parent
        if package != ROOT / "interfaces":
            files[package / "__init__.py"] = f'"""{BANNER}"""\n'
    return files


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if a generated file is out of date")
    args = parser.parse_args()
    stale = []
    for path, text in outputs(load()).items():
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current == text:
            continue
        stale.append(path.relative_to(ROOT))
        if not args.check:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
    if args.check and stale:
        print("Out of date:", *stale, sep="\n  ")
        return 1
    if not args.check:
        print(f"Generated {len(stale)} file(s)" if stale else "Up to date")
    return 0


if __name__ == "__main__":
    sys.exit(main())
